import{_ as n,C as s,o as d,c as o,j as t,E as e,a as r,a3 as l}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse(`{"title":"2-hafta (Mentor)","description":"","frontmatter":{"title":"2-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"n":2,"bob":"I-bob · Kompyuter savodxonligi va arxitekturasi","lessons":[{"g":4,"title":"Kompyuterning asosiy va qo'shimcha qurilmalari","lead":"Tizim bloki, monitor va klaviatura kompyuterning faqat «skeleti» xolos. Unga ulangan o'nlab qo'shimcha qurilmalar — printerlar, skanerlar, proyektorlar va drayverlar kompyuterni haqiqiy mo'jizaviy studiyaga aylantiradi. Ushbu darsda kompyuterning barcha a'zolari va ularni xavfsiz ulash sirlarini o'rganamiz.","link":"/mentor/8-sinf-cs/hafta-02/dars-1","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-1-test.html"},{"g":5,"title":"Internet, brauzerlar va elektron pochta bilan ishlash","lead":"Global tarmoq sirlari, brauzerlar anatomiyasi, Google'da professional qidiruv usullari hamda elektron pochtada xavfsiz va samarali ishlash madaniyati.","link":"/mentor/8-sinf-cs/hafta-02/dars-2","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-2-test.html"},{"g":6,"title":"Kompyuter xavfsizligi va antivirus dasturlari","lead":"Kompyuterni kiberxatarlardan himoyalash, zararli dasturlar turlari, antiviruslarning ishlash sirlari hamda mustahkam parollar yaratish madaniyati.","link":"/mentor/8-sinf-cs/hafta-02/dars-3","slide":"/slaydlar/8-sinf-cs/hafta-02/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-02/dars-3-test.html"}],"test":"/slaydlar/8-sinf-cs/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-02/index.md","filePath":"mentor/8-sinf-cs/hafta-02/index.md"}`),h={name:"mentor/8-sinf-cs/hafta-02/index.md"},g={class:"blk"},y={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},u={class:"blk"},c={id:"baholash-mezoni",tabindex:"-1"};function m(x,a,b,v,k,f){const i=s("Icon");return d(),o("div",null,[t("div",g,[t("h2",y,[e(i,{name:"house"}),a[0]||(a[0]=r(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=t("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=l('<p>Har bir vazifa 20–30 daqiqa vaqt oladi. Vazifalar daftarda yoki kompyuterda alohida papkada saqlanadi.</p><h2 id="_4-dars-uchun-kompyuterning-asosiy-va-qo-shimcha-qurilmalari" tabindex="-1">4-dars uchun (Kompyuterning asosiy va qo‘shimcha qurilmalari) <a class="header-anchor" href="#_4-dars-uchun-kompyuterning-asosiy-va-qo-shimcha-qurilmalari" aria-label="Permalink to &quot;4-dars uchun (Kompyuterning asosiy va qo‘shimcha qurilmalari)&quot;">​</a></h2><p><strong>1-topshiriq: «Periferiya qurilmalari va portlar xaritasi»</strong></p><ol><li>O&#39;zingiz yoki uyingizdagi kompyuterda mavjud bo&#39;lgan barcha portlarni (USB Type-A, Type-C, HDMI, Audio jack, RJ-45) sanab, har biriga qanday qurilma ulanganini daftaringizga yozing.</li><li><code>Win + X</code> tugmalari orqali <code>Device Manager</code>ni oching. «Display adapters» (Videokarta) va «Keyboards» (Klaviatura) bo&#39;limlarini ochib, qurilmalaringizning aniq ishlab chiqaruvchi modelini ko&#39;chiring.</li><li>Fleshkani kompyuterga ulab, vazifalar panelidagi o&#39;ng burchakdan «Safely Remove Hardware and Eject Media» amali orqali uni xavfsiz sug&#39;urish amaliyotini bajaring.</li></ol><p><strong>Kutiladigan natija:</strong> Kompyuterning jismoniy portlari va Device Manager orqali apparat ta&#39;minotini tahlil qilish ko&#39;nikmasi.</p><h2 id="_5-dars-uchun-internet-brauzerlar-va-elektron-pochta-bilan-ishlash" tabindex="-1">5-dars uchun (Internet, brauzerlar va elektron pochta bilan ishlash) <a class="header-anchor" href="#_5-dars-uchun-internet-brauzerlar-va-elektron-pochta-bilan-ishlash" aria-label="Permalink to &quot;5-dars uchun (Internet, brauzerlar va elektron pochta bilan ishlash)&quot;">​</a></h2><p><strong>2-topshiriq: «Google qidiruv va professional email»</strong></p><ol><li>Brauzeringizda (Chrome yoki Edge) <code>Ctrl + Shift + O</code> orqali xatcho&#39;plar menejerini oching va «IT Darsliklari» nomli alohida xatcho&#39;p papkasini yarating.</li><li>Google qidiruvida <code>site:</code> va <code>filetype:pdf</code> operatorlaridan foydalanib, O&#39;zbekiston saytlaridan informatika yoki dasturlash bo&#39;yicha 1 ta elektron qo&#39;llanmani toping va brauzeringizga saqlang.</li><li>Shaxsiy pochtangizdan (Gmail yoki maktab pochtasi) ustozingizga xat qoralamasi tayyorlang: <ul><li>Mavzu (Subject): «8-sinf CS 2-hafta uy vazifasi - [Ismingiz]»</li><li>Matn: Rasmiy xushmuomala salomlashish, topilgan kitob nomi va xulosa.</li><li>Fayl biriktirish (Attachment): Topilgan PDF darslikni xatga biriktiring.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> Qidiruv operatorlarini to&#39;g&#39;ri qo&#39;llash va professional darajada shakllantirilgan elektron xat loyihasi.</p><h2 id="_6-dars-uchun-kompyuter-xavfsizligi-va-antivirus-dasturlari" tabindex="-1">6-dars uchun (Kompyuter xavfsizligi va antivirus dasturlari) <a class="header-anchor" href="#_6-dars-uchun-kompyuter-xavfsizligi-va-antivirus-dasturlari" aria-label="Permalink to &quot;6-dars uchun (Kompyuter xavfsizligi va antivirus dasturlari)&quot;">​</a></h2><p><strong>3-topshiriq: «Kiberxavfsizlik auditi va kuchli parol»</strong></p><ol><li>Windows Security (yoki o&#39;rnatilgan antivirus) orqali «Quick scan» (Tezkor skanerlash) o&#39;tkazing. Tekshiruv natijasini (tekshirilgan fayllar soni va aniqlangan tahdidlar yo&#39;qligini) qayd eting.</li><li>Shaxsiy akkauntingiz (Google, Telegram yoki boshqa) uchun darsda o&#39;rganilgan formula (ibora + raqam + belgi) asosida 14 belgidan iborat kuchli parol tuzing va akkauntingizda 2FA (ikki bosqichli tasdiqlash) funksiyasini yoqing.</li><li>Kompyuteringizdagi eng muhim maktab fayllari va rasmlaringizni tashqi fleshkaga yoki bulutli xotiraga (Google Drive) zaxira nusxa (backup) sifatida nusxalang.</li></ol><p><strong>Kutiladigan natija:</strong> Antivirus bilan amaliy ishlash, shaxsiy hisoblarni 2FA bilan kuchaytirish va zaxira nusxa yaratish madaniyati.</p><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshidagi takrorlashda o&#39;quvchilar tomonidan tuzilgan qidiruv operatorlarini (<code>site:</code>, <code>filetype:</code>) doskada sinab ko&#39;ring. O&#39;quvchilar elektron xat yozishda <code>Subject</code> (Mavzu)ni to&#39;g&#39;ri to&#39;ldirishganiga va 2FA funksiyasini tushunib yetganiga e&#39;tibor qarating.</p>',15))]),t("div",u,[t("h2",c,[e(i,{name:"list-checks"}),a[3]||(a[3]=r(" Baholash mezoni ",-1)),a[4]||(a[4]=t("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=l('<p>Dasturdagi mezonlarga asoslangan (100 ballik shkala): <strong>90–100 — 5</strong>, <strong>71–89 — 4</strong>, <strong>60–70 — 3</strong>, <strong>0–59 — 2</strong>.</p><p>Dasturda joriy nazorat (amaliy mashg&#39;ulotlar, darsdagi faollik, tezkor savol-javoblar va uy vazifasi) o&#39;quv jarayoni davomida o&#39;tkaziladi. Quyida 2-haftaning 3 ta darsi bo&#39;yicha har bir o&#39;quvchi ishtirokini qayd etish uchun baholash jadvali keltirilgan.</p><h2 id="mezonlar-har-bir-dars-uchun" tabindex="-1">Mezonlar (har bir dars uchun) <a class="header-anchor" href="#mezonlar-har-bir-dars-uchun" aria-label="Permalink to &quot;Mezonlar (har bir dars uchun)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th style="text-align:center;">Max ball</th><th>Tavsif</th></tr></thead><tbody><tr><td>Nazariya va tushunchalar</td><td style="text-align:center;">30</td><td>Qurilmalar turlari, internet arxitekturasi, malware turlari va antivirus tamoyillarini bilishi</td></tr><tr><td>Amaliy ko&#39;nikmalar</td><td style="text-align:center;">30</td><td>Device Manager, Google qidiruv operatorlari, email yaratish, Windows Security skanerlash amallari</td></tr><tr><td>Kibergigiyena va texnika</td><td style="text-align:center;">20</td><td>Kuchli parol formulasi, 2FA tushunchasi, fleshkalarni xavfsiz ajratish va tekshirish</td></tr><tr><td>Uyga vazifa</td><td style="text-align:center;">20</td><td>Uy vazifasi to&#39;liq, sifatli va vaqtida bajarilgan</td></tr><tr><td><strong>Jami</strong></td><td style="text-align:center;"><strong>100</strong></td><td></td></tr></tbody></table><hr><h2 id="_4-dars-kompyuterning-asosiy-va-qo-shimcha-qurilmalari" tabindex="-1">4-dars (Kompyuterning asosiy va qo‘shimcha qurilmalari) <a class="header-anchor" href="#_4-dars-kompyuterning-asosiy-va-qo-shimcha-qurilmalari" aria-label="Permalink to &quot;4-dars (Kompyuterning asosiy va qo‘shimcha qurilmalari)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Kibergigiyena /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_5-dars-internet-brauzerlar-va-elektron-pochta-bilan-ishlash" tabindex="-1">5-dars (Internet, brauzerlar va elektron pochta bilan ishlash) <a class="header-anchor" href="#_5-dars-internet-brauzerlar-va-elektron-pochta-bilan-ishlash" aria-label="Permalink to &quot;5-dars (Internet, brauzerlar va elektron pochta bilan ishlash)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Kibergigiyena /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_6-dars-kompyuter-xavfsizligi-va-antivirus-dasturlari" tabindex="-1">6-dars (Kompyuter xavfsizligi va antivirus dasturlari) <a class="header-anchor" href="#_6-dars-kompyuter-xavfsizligi-va-antivirus-dasturlari" aria-label="Permalink to &quot;6-dars (Kompyuter xavfsizligi va antivirus dasturlari)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">Nazariya /30</th><th style="text-align:center;">Amaliyot /30</th><th style="text-align:center;">Kibergigiyena /20</th><th style="text-align:center;">Uy vazifasi /20</th><th style="text-align:center;">Jami</th><th style="text-align:center;">Baho</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr></tbody></table><hr><h2 id="_2-hafta-va-i-bob-yakuni" tabindex="-1">2-hafta va I bob yakuni <a class="header-anchor" href="#_2-hafta-va-i-bob-yakuni" aria-label="Permalink to &quot;2-hafta va I bob yakuni&quot;">​</a></h2><table tabindex="0"><thead><tr><th>O&#39;quvchi</th><th style="text-align:center;">4-dars</th><th style="text-align:center;">5-dars</th><th style="text-align:center;">6-dars</th><th style="text-align:center;">O&#39;rtacha ball</th><th style="text-align:center;">Yakuniy baho</th><th>Izoh va tavsiyalar</th></tr></thead><tbody><tr><td>1.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>2.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr><tr><td>3.</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td></td></tr></tbody></table><hr><h2 id="hafta-xulosasi-va-keyingi-bobga-ko-prik" tabindex="-1">Hafta xulosasi va keyingi bobga ko&#39;prik <a class="header-anchor" href="#hafta-xulosasi-va-keyingi-bobga-ko-prik" aria-label="Permalink to &quot;Hafta xulosasi va keyingi bobga ko&#39;prik&quot;">​</a></h2><p>2-hafta yakunida I bob — «Kompyuter savodxonligi va arxitekturasi» (jami 6 dars) to&#39;liq o&#39;zlashtirildi. O&#39;quvchilar apparat vositalari, operatsion tizim, tarmoq va xavfsizlik bo&#39;yicha mustahkam bazaga ega bo&#39;lishdi. Keyingi haftadan II bob boshlanadi: «Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari». 7-darsda 10 barmoqda tez yozish (Touch typing) metodikasi va klaviatura trenajyorlari bilan ishlash ko&#39;nikmalari o&#39;rganiladi.</p>',19))])])}const z=n(h,[["render",m]]);export{q as __pageData,z as default};
